-- Schede Classe 1-A: database completo (tabelle, sicurezza PIN, Realtime, Storage, dati attuali)
-- Incolla tutto in Supabase > SQL Editor > New query > Run. Va eseguito una volta sola.
create extension if not exists pgcrypto with schema extensions;

create table public.docs (
  col text not null check (col in ('schede','foto','png','scene','episodi','indizi','stato')),
  id  text not null check (length(id) between 1 and 200),
  data jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  primary key (col, id)
);
alter table public.docs enable row level security;
create policy "lettura pubblica" on public.docs for select to anon, authenticated using (true);

create table public.config (k text primary key, v text not null);
alter table public.config enable row level security;
revoke all on public.config from anon, authenticated;

create table public.pin_fail (at timestamptz not null default now());
alter table public.pin_fail enable row level security;
revoke all on public.pin_fail from anon, authenticated;

create or replace function public._pin_ok(p_pin text) returns boolean
language plpgsql security definer set search_path = public, extensions as $$
declare h text; n int;
begin
  select count(*) into n from pin_fail where at > now() - interval '15 minutes';
  if n >= 20 then return false; end if;
  select v into h from config where k = 'pin_hash';
  if h is null or p_pin is null or crypt(p_pin, h) <> h then
    insert into pin_fail default values;
    delete from pin_fail where at < now() - interval '1 day';
    return false;
  end if;
  return true;
end $$;
revoke all on function public._pin_ok(text) from public, anon, authenticated;

create or replace function public.check_pin(p_pin text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare n int;
begin
  select count(*) into n from pin_fail where at > now() - interval '15 minutes';
  if n >= 20 then return jsonb_build_object('ok', false, 'err', 'bloccato'); end if;
  return jsonb_build_object('ok', _pin_ok(p_pin), 'err', null);
end $$;

create or replace function public.put_doc(p_col text, p_id text, p_data jsonb, p_pin text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  if p_col not in ('schede','foto') and not _pin_ok(p_pin) then
    return jsonb_build_object('ok', false, 'err', 'pin');
  end if;
  if octet_length(p_data::text) > 900000 then
    return jsonb_build_object('ok', false, 'err', 'troppo_grande');
  end if;
  insert into docs (col, id, data, updated_at) values (p_col, p_id, coalesce(p_data,'{}'::jsonb), now())
  on conflict (col, id) do update set data = excluded.data, updated_at = now();
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.del_doc(p_col text, p_id text, p_pin text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  if p_col not in ('schede','foto') and not _pin_ok(p_pin) then
    return jsonb_build_object('ok', false, 'err', 'pin');
  end if;
  delete from docs where col = p_col and id = p_id;
  return jsonb_build_object('ok', true);
end $$;

revoke all on function public.check_pin(text), public.put_doc(text,text,jsonb,text), public.del_doc(text,text,text) from public;
grant execute on function public.check_pin(text), public.put_doc(text,text,jsonb,text), public.del_doc(text,text,text) to anon, authenticated, service_role;

alter publication supabase_realtime add table public.docs;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('immagini', 'immagini', true, 5242880, array['image/jpeg','image/png','image/webp','image/gif']);

